import{_ as t,H as E,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"打卡召集令 | 60 天攻克数据结构与算法","description":"","frontmatter":{},"headers":[],"relativePath":"数据结构与算法之美/打卡召集令-60天攻克数据结构与算法.md","filePath":"数据结构与算法之美/打卡召集令-60天攻克数据结构与算法.md","lastUpdated":1779820813000}'),s={name:"数据结构与算法之美/打卡召集令-60天攻克数据结构与算法.md"};function i(r,e,p,o,B,g){return E(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="打卡召集令-60-天攻克数据结构与算法" tabindex="-1">打卡召集令 | 60 天攻克数据结构与算法 <a class="header-anchor" href="#打卡召集令-60-天攻克数据结构与算法" aria-label="Permalink to &quot;打卡召集令 | 60 天攻克数据结构与算法&quot;">​</a></h1><p>你好，我是王争。</p><p>今年4月，专栏更新结束之后，我在专栏发布了一篇 <a href="https://time.geekbang.org/column/article/91541" target="_blank" rel="noreferrer">《数据结构与算法之美》学习指导手册》</a>，在这篇文章里，我对专栏内容重新做了一次梳理，将整个专栏拆分成四个阶段，列出了每个阶段的核心知识点、标注了每个知识点的难易程度（E-Easy，M-Medium，H-Hard），并用 1-10 分说明其重要性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/3eb147a56e5b1452692fbbd4498075b7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/3eb147a56e5b1452692fbbd4498075b7.png" alt="unpreview"></a></p><p>但是，我发现，很多同学还是没能坚持下来，久而久之对学习算法失去了信心。</p><p>回想起来，写专栏之初，我就立下 Flag，要做一个跟国内外经典书籍不一样、可以长期影响一些人的专栏。所以，在专栏完结 9 个月后，我想再做一些事情。</p><p>为了带你彻底拿下“数据结构与算法”这座大山，我发起了 <strong>“60 天攻克数据结构与算法”打卡行动</strong>，一起登顶！</p><p>下面是我为你精心规划的学习计划表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/12a5a67041dbd5c1e65d72f0fbe4c86e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/12a5a67041dbd5c1e65d72f0fbe4c86e.jpg" alt=""></a></p><p><strong>活动时间</strong>：2019.11.25-2020.1.19</p><p><strong>你将获得</strong>：</p><p>1.坚持 60 天，与 2000 位优秀的工程师一起，彼此激励，相互学习；</p><p>2.整个学习周期内，我会进行2次高质量的社群分享；</p><p>3.我会精心整理 4 张知识脑图，为你梳理每个阶段的学习重点，发布在专栏里；</p><p>4.我和极客时间准备了 20 万奖学金，给坚持下来的同学。</p><p><strong>活动规则</strong>：</p><p>在下方申请进入活动打卡群，根据课表打卡，完成学习。</p><p><a href="https://jinshuju.net/f/DYtafE" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/f7f62d8fbf411f179cd16c914e0151e6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/f7f62d8fbf411f179cd16c914e0151e6.png" alt="unpreview"></a></a></p><p><strong>打卡要求</strong>：</p><p>1.每个阶段持续 2 周，每周仅需打卡 3 次，即视为完成该阶段的学习。</p><p>2.4个阶段（8 周）的学习，打卡总数仅需 30 次，即视为完成“60 天攻克数据结构与算法行动”。</p><p>3.为了让大家养成习惯，每日只计 1 次打卡，单日内多次打卡视为 1 次。</p><p><strong>进入打卡群后，完成学习还有如下奖励</strong>：</p><ul><li>第一阶段（第1-2周）：¥15 奖励金</li><li>第二阶段（第3-4周）：¥25 奖励金</li><li>第三阶段（第5-6周）：¥35 奖励金</li><li>四个阶段（第7-8周）：¥50 奖励金</li></ul><p>（注：奖励金会以无门槛优惠券形式、分阶段进行发放，发放时间为每阶段结束后的 7 个工作日内。）</p><p>当然，优惠券只是对你的小小奖励。坚持 60 天，与 2000 位优秀的工程师一起，互相学习，彼此激励，彻底拿下数据结构与算法，我奉陪到底。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/a63516bc3b13ae1a18adcbb83c969888.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/168882/a63516bc3b13ae1a18adcbb83c969888.png" alt="unpreview"></a></p>',27)])])}const c=t(s,[["render",i]]);export{l as __pageData,c as default};
